let globalData = 'Global Data';

function checkScope() {
  // We can access global variables inside functions
  console.log('Inside function:', globalData);

  let secretData = 'Secret Local Data';
  console.log('Inside function:', secretData);
}

checkScope();

// We can access global data outside
console.log('Outside function:', globalData);

