// Create an Array using square brackets [ ]
let fruits = ['Apple', 'Banana', 'Mango'];

// Access items using their Index number in square brackets
console.log(fruits[0]); // Gets the 1st item (Apple)
console.log(fruits[1]); // Gets the 2nd item (Banana)

// Arrays have a built-in property called .length
// It tells you exactly how many items are in the list.
console.log('Total fruits:', fruits.length);

let colors = ['Red', 'Blue'];
console.log('Original:', colors);

// 1. Update an existing item (replace Blue with Green)
colors[1] = 'Green';
console.log('Updated:', colors);

// 2. Add a new item to the end using the .push() method
colors.push('Yellow');
console.log('After Push:', colors);
